// Regenerate the TWO docs footers (Mintlify) from lib/footer-links.json —
// the same single source components/Footer.tsx imports. This kills the
// three-copies drift that left docs showing pre-pivot links and the old
// tagline ("Operator-grade") days after the site moved on.
//
// Writes:
//   docs/footer.js   — custom JS that replaces Mintlify's footer (AUTO-GENERATED)
//   docs/docs.json   — only the "footer" key is touched; everything else preserved
//
// Usage:  node scripts/refresh-docs-footer.mjs
// After any footer change: edit lib/footer-links.json → run this → commit all three.

import { readFileSync, writeFileSync } from "node:fs"

const SRC = new URL("../lib/footer-links.json", import.meta.url)
const OUT_JS = new URL("../docs/footer.js", import.meta.url)
const OUT_JSON = new URL("../docs/docs.json", import.meta.url)

const data = JSON.parse(readFileSync(SRC, "utf8"))
const abs = (h) => (h.startsWith("/") ? "https://solidstate.cc" + h : h)

// --- docs.json: patch only the footer key, preserve the rest verbatim-ish ---
const dj = JSON.parse(readFileSync(OUT_JSON, "utf8"))
dj.footer = {
  links: data.cols.map((c) => ({
    header: c.title,
    items: c.links.map((l) => ({ label: l.label, href: abs(l.href) })),
  })),
}
writeFileSync(OUT_JSON, JSON.stringify(dj, null, 2) + "\n")

// --- footer.js: full file, generated ---
const colsLiteral = JSON.stringify(
  data.cols.map((c) => ({
    title: c.title,
    links: c.links.map((l) => [abs(l.href), l.label, !!l.external]),
  })),
  null,
  2
)

const js = `// AUTO-GENERATED by scripts/refresh-docs-footer.mjs from lib/footer-links.json.
// Do not edit by hand — edit the JSON source and re-run the script.
// Replaces Mintlify's footer with the site footer (mirrors components/Footer.tsx).
(function () {
  var EXT = ' \\u2197';
  var TAGLINE = ${JSON.stringify(data.tagline)};
  var BUILT_BY = ${JSON.stringify(data.builtBy)};
  var COLS = ${colsLiteral};

  function colHtml(col) {
    var links = col.links
      .map(function (l) {
        return (
          '<li style="margin-bottom:8px"><a href="' + l[0] + '"' +
          (l[2] ? ' target="_blank" rel="noopener noreferrer"' : '') +
          ' style="font-size:13px;color:var(--ss-fg);text-decoration:none">' +
          l[1] + (l[2] ? EXT : '') + '</a></li>'
        );
      })
      .join('');
    return (
      '<div><div style="font-family:\\'JetBrains Mono\\',monospace;font-size:10px;color:var(--ss-f-muted);letter-spacing:0.12em;text-transform:uppercase;margin-bottom:16px">' +
      col.title +
      '</div><ul style="list-style:none;padding:0;margin:0">' + links + '</ul></div>'
    );
  }

  function footerHtml() {
    var year = new Date().getFullYear();
    return (
      '<div style="border-top:1px solid var(--ss-border);background:var(--ss-bg);color:var(--ss-fg);width:100%">' +
      '<div style="max-width:1200px;margin:0 auto;padding:56px 32px 32px">' +
      '<div class="ss-footer-grid" style="display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:32px;margin-bottom:48px">' +
      '<div><div style="display:flex;align-items:center;gap:10px;color:var(--ss-fg)">' +
      '<svg aria-hidden="true" width="16" height="16" viewBox="0 0 32 32" fill="currentColor" xmlns="http://www.w3.org/2000/svg" style="display:block;flex-shrink:0">' +
      '<rect x="4" y="6" width="6" height="20" rx="1"></rect><rect x="13" y="6" width="6" height="20" rx="1"></rect><rect x="22" y="6" width="6" height="20" rx="1"></rect></svg>' +
      '<img src="https://solidstate.cc/logo-white.png" alt="Solid State" class="ss-invertible" style="display:block;height:15px;width:auto">' +
      '</div>' +
      '<p style="font-size:13px;color:var(--ss-f-muted);line-height:1.7;margin-top:16px;max-width:300px">' + TAGLINE + ' Built by ' +
      '<a href="' + BUILT_BY.href + '" target="_blank" rel="noopener noreferrer" style="color:var(--ss-fg);text-decoration:none">' + BUILT_BY.label + '</a>.</p></div>' +
      COLS.map(colHtml).join('') +
      '</div>' +
      '<div style="border-top:1px solid var(--ss-border);padding-top:24px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px">' +
      '<span style="font-family:\\'JetBrains Mono\\',monospace;font-size:11px;color:var(--ss-f-muted);letter-spacing:0.06em;text-transform:uppercase">\\u00a9 ' + year + ' Solid State \\u00b7 ' +
      '<a href="https://visionaire.co" target="_blank" rel="noopener noreferrer" style="color:inherit;text-decoration:none">Visionaire Labs \\u2197</a></span>' +
      '<span style="font-family:\\'JetBrains Mono\\',monospace;font-size:11px;color:var(--ss-f-muted);letter-spacing:0.06em;text-transform:uppercase">solidstate.cc</span>' +
      '</div>' +
      '<div style="padding-top:16px"><a href="https://mintlify.com" target="_blank" rel="noopener noreferrer" style="font-size:11px;color:var(--ss-f-dim);text-decoration:none">Powered by Mintlify</a></div>' +
      '</div></div>'
    );
  }

  function apply() {
    var f = document.getElementById('footer');
    if (!f || f.dataset.ssFooter === '1') return;
    f.dataset.ssFooter = '1';
    f.innerHTML = footerHtml();
    f.style.padding = '0';
    f.style.border = 'none';
  }

  apply();
  new MutationObserver(apply).observe(document.documentElement, { childList: true, subtree: true });
})();
`
writeFileSync(OUT_JS, js)
console.log(
  `Regenerated docs/footer.js + docs/docs.json footer from lib/footer-links.json (${data.cols.reduce((n, c) => n + c.links.length, 0)} links, tagline: "${data.tagline.slice(0, 40)}…")`
)
